nt","country":"Madagascar","content":{"sections":[{"heading":"When required","text":"","references":[]},{"heading":"Requirements","text":"","references":[]},{"heading":"Fields to extract","text":"","references":[]},{"heading":"Cross-document checks","text":"","references":[]},{"heading":"If missing or incorrect","text":"","references":[]},{"heading":"Examples and templates","text":"","references":[]},{"heading":"Sources","text":"","references":[]}],"rules":[{"id":"mg-required-mg-document-bill-of-lading","country":"Madagascar","document":"Bill of Lading","instruction":"Required document.","requirement":"always required","condition":"","stage":"intake","consequence":"","sourceIds":["mg-current-working-instructions"],"effectiveFrom":"","effectiveTo":"","kind":"document","check":{"operator":"present","fieldIds":[],"expected":""}},{"id":"mg-bill-of-lading-final-dated-mbl","country":"Madagascar","document":"Bill of Lading","instruction":"A final, dated master Bill of Lading is required.","requirement":"always required","condition":"","stage":"intake","consequence":"Flag the request for staff review.","sourceIds":["mg-current-working-instructions"],"effectiveFrom":"","effectiveTo":"","kind":"acceptance","check":{"operator":"interpret","fieldIds":["mg-source-billOfLadingDate"],"expected":"final master Bill of Lading with a stated date"}}],"fields":[{"id":"mg-source-exporterName","label":"Exporter name","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["exporterName"],"ruleIds":[]},{"id":"mg-source-importerName","label":"Importer name","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["importerName"],"ruleIds":[]},{"id":"mg-source-shipmentMethod","label":"Shipment Method","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Return Sea for an ocean, liner, sea waybill or maritime Bill of Lading. Return Air for an airway bill or air waybill. Do not infer another method.","portalFieldIds":["shipmentMethod"],"ruleIds":[]},{"id":"mg-source-cargoType","label":"Cargo Type","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Return Full container load when the Bill of Lading identifies one or more shipping containers. Otherwise use only an explicitly supported cargo type and leave blank when it cannot be determined.","portalFieldIds":["cargoType"],"ruleIds":[]},{"id":"mg-source-grossWeight","label":"Gross Weight","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Return the total gross shipment weight required by the certificate, normalized to kilograms as a decimal number without a unit suffix. Prefer an explicitly labeled total gross weight. Convert another explicit weight unit to kilograms only when the source unit is clear.","portalFieldIds":["grossWeight"],"ruleIds":[]},{"id":"mg-source-volume","label":"Volume","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Return explicit shipment volume in cubic metres as a decimal number without a unit suffix. If volume is absent but container sizes are explicit, use 25 per 20-foot container and 50 per 40-foot container and sum multiple containers. Otherwise leave blank.","portalFieldIds":["volume"],"ruleIds":[]},{"id":"mg-source-shippingLine","label":"Shipping Line","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["shippingLine"],"ruleIds":[]},{"id":"mg-source-voyage","label":"Voyage","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["voyage"],"ruleIds":[]},{"id":"mg-source-vessel","label":"Vessel","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["vessel"],"ruleIds":[]},{"id":"mg-source-containerNumber","label":"Container Number","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["containerNumber"],"ruleIds":[]},{"id":"mg-source-containerType","label":"Container Type","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Normalize container notation to an allowed certificate option. RF or RH means Reefer; OT means Open Top; FR means FlatRack; TK means Tank; DV, DC, GP, HC or HQ normally means Dry unless other evidence establishes a different type. Use the full container code and description together and leave blank if uncertain.","portalFieldIds":["containerType"],"ruleIds":[]},{"id":"mg-source-containerSize","label":"Container Size","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Normalize an explicit container size to the exact allowed certificate option: a 20-foot code to 20 Feet and a 40-foot code to 40 Feet. Use Other for another explicit length. Leave blank when no size is stated or encoded.","portalFieldIds":["containerSize"],"ruleIds":[]},{"id":"mg-source-sealNumber","label":"Seal Number","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["sealNumber"],"ruleIds":[]},{"id":"mg-source-loadingCountry","label":"Loading Country","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Return the country containing the named port or place of loading, using the exact allowed country name. Geographic lookup is permitted when the port is explicit; for example, Newark is in the United States.","portalFieldIds":["loadingCountry"],"ruleIds":[]},{"id":"mg-source-loadingDate","label":"Loading Date","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Use an explicitly stated departure or shipped-on-board date and normalize it to YYYY-MM-DD. Do not invent a current schedule date; leave blank for later carrier tracking when it is not in the documents.","portalFieldIds":["loadingDate"],"ruleIds":[]},{"id":"mg-source-loadingCity","label":"Loading City","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["loadingCity"],"ruleIds":[]},{"id":"