with seed(page) as (select value from jsonb_array_elements('[{"id":"standards","title":"Standards","template":"standards","country":"Shared","content":{"sections":[{"heading":"Structure","text":"","references":[]},{"heading":"Page templates","text":"","references":[]},{"heading":"Writing rules","text":"Write only operational knowledge. Use short Markdown sentences and bullets. Edit requirements, extraction instructions, process notes, and exceptions as text. Do not edit stable IDs, sources, mappings, form fields, headings, or metadata through routine text editing. Use AI Update with evidence for new rules, sources, links, or structural proposals. Keep one rule in one canonical document page and link to it elsewhere. Leave unsupported or ambiguous values unconfirmed.","references":[]},{"heading":"Approval rules","text":"Direct text edits create a draft and preserve all protected metadata. New rules, changed requirements, contradictions, exceptions, deletions, and structural changes require a reviewed proposal before publication. Duplicate updates make no change.","references":[]},{"heading":"Versioning","text":"Use major versions for approved structural changes, minor versions for operational changes, and patch versions for wording that does not change meaning. Formatting-only and duplicate updates do not create versions.","references":[]}],"rules":[],"fields":[],"mappings":[],"sources":[],"aliases":[]},"revision":0,"version":null,"publishedAt":null},{"id":"shared-process","title":"Shared Process","template":"process","country":"Shared","content":{"sections":[{"heading":"1. Intake","text":"","references":[]},{"heading":"2. Drafting","text":"","references":[]},{"heading":"3. Submission","text":"","references":[]},{"heading":"4. Validation","text":"","references":[]},{"heading":"5. Release","text":"","references":[]}],"rules":[],"fields":[],"mappings":[],"sources":[],"aliases":[]},"revision":0,"version":null,"publishedAt":null},{"id":"country-index","title":"Country In