country":"Madagascar","content":{"sections":[{"heading":"When required","text":"","references":[]},{"heading":"Requirements","text":"","references":[]},{"heading":"Fields to extract","text":"","references":[]},{"heading":"Cross-document checks","text":"","references":[]},{"heading":"If missing or incorrect","text":"","references":[]},{"heading":"Examples and templates","text":"","references":[]},{"heading":"Sources","text":"","references":[]}],"rules":[{"id":"mg-required-mg-document-bill-of-lading","country":"Madagascar","document":"Bill of Lading","instruction":"Required document.","requirement":"always required","condition":"","stage":"intake","consequence":"","sourceIds":["mg-current-working-instructions"],"effectiveFrom":"","effectiveTo":"","kind":"document","check":{"operator":"present","fieldIds":[],"expected":""}},{"id":"mg-bill-of-lading-final-dated-mbl","country":"Madagascar","document":"Bill of Lading","instruction":"A final, dated master Bill of Lading is required.","requirement":"always required","condition":"","stage":"intake","consequence":"Flag the request for staff review.","sourceIds":["mg-current-working-instructions"],"effectiveFrom":"","effectiveTo":"","kind":"acceptance","check":{"operator":"interpret","fieldIds":["mg-source-billOfLadingDate"],"expected":"final master Bill of Lading with a stated date"}}],"fields":[{"id":"mg-source-exporterName","label":"Exporter name","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["exporterName"],"ruleIds":[]},{"id":"mg-source-importerName","label":"Importer name","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["importerName"],"ruleIds":[]},{"id":"mg-source-shipmentMethod","label":"Shipment Method","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Return Sea for an ocean, liner, sea waybill or maritime Bill of Lading. Return Air for an airway bill or air waybill. Do not infer another method.","portalFieldIds":["shipmentMethod"],"ruleIds":[]},{"id":"mg-source-cargoType","label":"Cargo Type","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Return Full container load when the Bill of Lading identifies one or more shipping containers. Otherwise use only an explicitly supported cargo type and leave blank when it cannot be determined.","portalFieldIds":["cargoType"],"ruleIds":[]},{"id":"mg-source-grossWeight","label":"Gross Weight","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Return the total gross shipment weight required by the certificate, normalized to kilograms as a decimal number without a unit suffix. Prefer an explicitly labeled total gross weight. Convert another explicit weight unit to kilograms only when the source unit is clear.","portalFieldIds":["grossWeight"],"ruleIds":[]},{"id":"mg-source-volume","label":"Volume","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Return explicit shipment volume in cubic metres as a decimal number without a unit suffix. If volume is absent but container sizes are explicit, use 25 per 20-foot container and 50 per 40-foot container and sum multiple containers. Otherwise leave blank.","portalFieldIds":["volume"],"ruleIds":[]},{"id":"mg-source-shippingLine","label":"Shipping Line","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["shippingLine"],"ruleIds":[]},{"id":"mg-source-voyage","label":"Voyage","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["voyage"],"ruleIds":[]},{"id":"mg-source-vessel","label":"Vessel","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["vessel"],"ruleIds":[]},{"id":"mg-source-containerNumber","label":"Container Number","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["containerNumber"],"ruleIds":[]},{"id":"mg-source-containerType","label":"Container Type","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Normalize container notation to an allowed certificate option. RF or RH means Reefer; OT means Open Top; FR means FlatRack; TK means Tank; DV, DC, GP, HC or HQ normally means Dry unless other evidence establishes a different type. Use the full container code and description together and leave blank if uncertain.","portalFieldIds":["containerType"],"ruleIds":[]},{"id":"mg-source-containerSize","label":"Container Size","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Normalize an explicit container size to the exact allowed certificate option: a 20-foot code to 20 Feet and a 40-foot code to 40 Feet. Use Other for another explicit length. Leave blank when no size is stated or encoded.","portalFieldIds":["containerSize"],"ruleIds":[]},{"id":"mg-source-sealNumber","label":"Seal Number","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["sealNumber"],"ruleIds":[]},{"id":"mg-source-loadingCountry","label":"Loading Country","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Return the country containing the named port or place of loading, using the exact allowed country name. Geographic lookup is permitted when the port is explicit; for example, Newark is in the United States.","portalFieldIds":["loadingCountry"],"ruleIds":[]},{"id":"mg-source-loadingDate","label":"Loading Date","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Use an explicitly stated departure or shipped-on-board date and normalize it to YYYY-MM-DD. Do not invent a current schedule date; leave blank for later carrier tracking when it is not in the documents.","portalFieldIds":["loadingDate"],"ruleIds":[]},{"id":"mg-source-loadingCity","label":"Loading City","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["loadingCity"],"ruleIds":[]},{"id":"mg-source-unloadingCountry","label":"Unloading Country","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["unloadingCountry"],"ruleIds":[]},{"id":"mg-source-unloadingDate","label":"Unloading Date","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Use an explicitly stated arrival or unloading date and normalize it to YYYY-MM-DD. Do not invent a current schedule date; leave blank for later carrier tracking when it is not in the documents.","portalFieldIds":["unloadingDate"],"ruleIds":[]},{"id":"mg-source-unloadingCity","label":"Unloading City","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"","portalFieldIds":["unloadingCity"],"ruleIds":[]},{"id":"mg-source-billOfLadingReference","label":"BL Reference","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Return only the Bill of Lading or waybill number. Remove labels and words before it. Remove hyphens and other decorative punctuation, but preserve forward slashes.","portalFieldIds":["billOfLadingReference"],"ruleIds":[]},{"id":"mg-source-billOfLadingDate","label":"BL Issuance Date","document":"Bill of Lading","location":"","requiredWhen":"","instruction":"Read the Bill of Lading or waybill issue date and normalize it to YYYY-MM-DD. Keep shipped-on-board and issue dates distinct. Leave blank if the issue date is not present.","portalFieldIds":["billOfLadingDate"],"ruleIds":[]}],"mappings":[],"sources":[],"aliases":[]},"revision":0,"version":null,"publishedAt":null},{"id":"mg-document-commercial-invoice","title":"Commercial Invoice","template":"document","country":"Madagascar","content":{"sections":[{"heading":"When required","text":"","references":[]},{"heading":"Requirements","text":"","references":[]},{"heading":"Fields to extract","text":"","references":[]},{"heading":"Cross-document checks","text":"","references":[]},{"heading":"If missing or incorrect","text":"","references":[]},{"heading":"Examples and templates","text":"","references":[]},{"heading":"Sources","text":"","references":[]}],"rules":[{"id":"mg-required-mg-document-commercial-invoice","country":"Madagascar","document":"Commercial Invoice","instruction":"Required document.","requirement":"always required","condition":"","stage":"intake","consequence":"","sourceIds":["mg-current-working-instructions"],"effectiveFrom":"","effectiveTo":"","kind":"document","check":{"operator":"present","fieldIds":[],"expected":""}},{"id":"madagascar-commercial-invoice-parties","country":"Madagascar","document":"Commercial Invoice","instruction":"Require the seller/exporter name or company name and exact address, plus the buyer/importer name or company name, exact address, and Tax Identification Number.","requirement":"always required","condition":"","stage":"intake","consequence":"","sourceIds":["mg-current-working-instructions"],"effectiveFrom":"","effectiveTo":"","kind":"acceptance","check":{"operator":"interpret","fieldIds":[],"expected":""}},{"id":"madagascar-commercial-invoice-reference","country":"Madagascar","document":"Commercial Invoice","instruction":"Require an issue date and a sequential, continuous commercial invoice number.","requirement":"always required","condition":"","stage":"intake","consequence":"","sourceIds":["mg-current-working-instructions"],"effectiveFrom":"","effectiveTo":"","kind":"acceptance","check":{"operator":"interpret","fieldIds":[],"expected":""}},{"id":"madagascar-commercial-invoice-goods","country":"Madagascar","document":"Commercial Invoice","instruction":"Require a precise goods description suitable for HS classification, including brand, reference, origin, characteristics, and packaging.","requirement":"always required","condition":"","stage":"intake","consequence":"","sourceIds":["mg-current-working-instructions"],"effectiveFrom":"","effectiveTo":"","kind":"acceptance","check":{"operator":"interpret","fieldIds":[],"expected":""}},{"id":"madagascar-commercial-invoice-values","country":"Madagascar","document":"Commercial Invoice","instruction":"Require detailed quantity, unit price with currency, total goods price, and total invoice amount in figures and words.","requirement":"always required","condition":"","stage":"intake","consequence":"","sourceIds":["mg-current-working-instructions"],"effectiveFrom":"","effectiveTo":"","kind":"acceptance","check":{"operator":"interpret","fieldIds":[],"expected":""}},{"id":"madagascar-commercial-invoice-terms","country":"Madagascar","document":"Commercial Invoice","instruction":"Require the Incoterm, payment method, and exporter signature.","requirement":"always required","condition":"","stage":"intake","consequence":"","sourceIds":["mg-current-working-instructions"],"effectiveFrom":"","effectiveTo":"","kind":"acceptance","check":{"operator":"interpret","fieldIds":[],"expected":""}},{"id":"mg-commercial-invoice-country-of-origin","country":"Madagascar","document":"Commercial Invoice","instruction":"Country of origin must be stated.","requirement":"always required","condition":"","stage":"intake","consequence":"Flag the request for staff review.","sourceIds":["mg-current-working-instructions"],"effectiveFrom":"","effectiveTo":"","kind":"acceptance","check":{"operator":"present","fieldIds":["mg-source-invoiceItems-originCountry"],"expected":""}}],"fields":[{"id":"mg-source-exporterAddress","label":"Exporter address","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"","portalFieldIds":["exporterAddress"],"ruleIds":[]},{"id":"mg-source-exporterCountry","label":"Exporter country","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"","portalFieldIds":["exporterCountry"],"ruleIds":[]},{"id":"mg-source-importerAddress","label":"Importer address","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"","portalFieldIds":["importerAddress"],"ruleIds":[]},{"id":"mg-source-importerCountry","label":"Importer country","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"","portalFieldIds":["importerCountry"],"ruleIds":[]},{"id":"mg-source-incoterm","label":"Incoterm","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"Read an explicitly stated Incoterm first. If it is absent, infer it from the Commercial Invoice''s value composition: when the only stated total is Commercial Value, Goods Value, Merchandise Value or an equivalent goods total and the invoice does not add freight or insurance, return FOB; use CFR when the invoiced total includes goods plus freight; use CIF when the invoiced total includes goods plus freight plus insurance. A separately itemized freight or insurance amount is evidence of inclusion only when the invoice total or wording shows that it is part of the invoiced value. The commercial-value-only case must not be left blank merely because the letters FOB are not printed. Return the three-letter uppercase term and keep it consistent with Incoterm Place and FOB Value. Leave blank only when the documented amounts genuinely support more than one case.","portalFieldIds":["incoterm"],"ruleIds":[]},{"id":"mg-source-incotermPlace","label":"Incoterm Place","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"Derive this together with Incoterm. For FOB, use the named port or place of loading. For CFR or CIF, use the named destination or port of discharge. Prefer the place printed beside the Incoterm, then the corresponding named port elsewhere on the Commercial Invoice. Preserve the port or city name. Leave blank only when the invoice does not identify the required place.","portalFieldIds":["incotermPlace"],"ruleIds":[]},{"id":"mg-source-fobValue","label":"FOB Value","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"Return the total FOB goods value as a decimal number without a currency symbol or thousands separators. Prefer an explicitly labeled FOB total. Otherwise derive it from the Commercial Invoice: for FOB, use the total commercial or goods value; for CFR, subtract separately stated freight from the CFR invoice total; for CIF, subtract separately stated freight and insurance from the CIF invoice total. If no reliable total is printed but all line amounts are present, sum the line amounts; calculate quantity multiplied by unit price only when needed. Derive this together with Incoterm and Incoterm Place, use only amounts from this invoice, and leave blank if the necessary components are ambiguous or incomplete.","portalFieldIds":["fobValue"],"ruleIds":[]},{"id":"mg-source-currency","label":"Currency","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"Return an ISO currency code. Normalize an unambiguous symbol: $ to USD, € to EUR and £ to GBP. Use document context when a symbol can denote more than one currency; leave blank if it remains ambiguous.","portalFieldIds":["currency"],"ruleIds":[]},{"id":"mg-source-commercialInvoiceReference","label":"Commercial Invoice Reference","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"Return only the reference value. Remove labels and words before it, such as Invoice or Invoice #. Remove hyphens and other decorative punctuation, but preserve forward slashes. Example: Invoice # 81 becomes 81.","portalFieldIds":["commercialInvoiceReference"],"ruleIds":[]},{"id":"mg-source-commercialInvoiceDate","label":"Commercial Invoice Issuance Date","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"Read the invoice issue date and normalize it to YYYY-MM-DD. Resolve day and month order from the document''s locale and surrounding text. Leave blank if the date is incomplete or genuinely ambiguous.","portalFieldIds":["commercialInvoiceDate"],"ruleIds":[]},{"id":"mg-source-invoiceItems-hsCode","label":"HS Code","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"","portalFieldIds":["invoiceItems.hsCode"],"ruleIds":[]},{"id":"mg-source-invoiceItems-description","label":"Description","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"","portalFieldIds":["invoiceItems.description"],"ruleIds":[]},{"id":"mg-source-invoiceItems-quantity","label":"Quantity","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"","portalFieldIds":["invoiceItems.quantity"],"ruleIds":[]},{"id":"mg-source-invoiceItems-unitOfMeasurement","label":"Unit of Measurement","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"","portalFieldIds":["invoiceItems.unitOfMeasurement"],"ruleIds":[]},{"id":"mg-source-invoiceItems-unitPrice","label":"Unit FOB Value","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"","portalFieldIds":["invoiceItems.unitPrice"],"ruleIds":[]},{"id":"mg-source-invoiceItems-isSecondHand","label":"Is Second Hand","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"","portalFieldIds":["invoiceItems.isSecondHand"],"ruleIds":[]},{"id":"mg-source-invoiceItems-originCountry","label":"Country","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"","portalFieldIds":["invoiceItems.originCountry"],"ruleIds":[]},{"id":"mg-source-invoiceValues","label":"Invoice Values","document":"Commercial Invoice","location":"","requiredWhen":"","instruction":"","portalFieldIds":["invoiceValues"],"ruleIds":[]}],"mappings":[],"sources":[],"aliases":[]},"revision":0,"version":null,"publishedAt":null},{"id":"mg-document-freight-invoice","title":"Freight Invoice","template":"document","country":"Madagascar","content":{"sections":[{"heading":"When required","text":"","references":[]},{"heading":"Requirements","text":"","references":[]},{"heading":"Fields to extract","text":"","references":[]},{"heading":"Cross-document checks","text":"","references":[]},{"heading":"If missing or incorrect","text":"","references":[]},{"heading":"Examples and templates","text":