,"fieldIds":[],"expected":""}},{"id":"madagascar-packing-list-other","country":"Madagascar","document":"Packing List","instruction":"Require precise identification of every package, airway bill package count and total weight where applicable, package numbers or markings, quantity, weight, and item description per package.","requirement":"always required","condition":"","stage":"intake","consequence":"","sourceIds":["mg-current-working-instructions"],"effectiveFrom":"","effectiveTo":"","kind":"acceptance","check":{"operator":"interpret","fieldIds":[],"expected":""}}],"fields":[{"id":"mg-source-packingListReference","label":"Packing List Reference","document":"Packing List","location":"","requiredWhen":"","instruction":"Return only the reference value. Remove labels and words before it. Remove hyphens and other decorative punctuation, but preserve forward slashes.","portalFieldIds":["packingListReference"],"ruleIds":[]},{"id":"mg-source-packingListDate","label":"Packing List Issuance Date","document":"Packing List","location":"","requiredWhen":"","instruction":"Read the packing-list issue date and normalize it to YYYY-MM-DD. Leave blank if the date is incomplete or genuinely ambiguous.","portalFieldIds":["packingListDate"],"ruleIds":[]}],"mappings":[],"sources":[],"aliases":[]},"revision":0,"version":null,"publishedAt":null},{"id":"mg-document-export-customs-declaration","title":"Export/Customs Declaration","template":"document","country":"Madagascar","content":{"sections":[{"heading":"When required","text":"","references":[]},{"heading":"Requirements","text":"","references":[]},{"heading":"Fields to extract","text":"","references":[]},{"heading":"Cross-document checks","text":"","references":[]},{"heading":"If missing or incorrect","text":"","references":[]},{"heading":"Examples and templates","text":"","references":[]},{"heading":"Sources","text":"","references":[]}],"rules":[{"id":"mg-required-mg-document-export-customs-declaration","country":"Madagascar","document":"Export/Customs Declaration","instruction":"Required document.","requirement":"always required","condition":"","stage":"intake","consequence":"","sourceIds":["mg-current-working-instructions"],"effectiveFrom":"","effectiveTo":"","kind":"document","check":{"operator":"present","fieldIds":[],"expected":""}}],"fields":[{"id":"mg-source-exportDeclarationReference","label":"Export Declaration Reference","document":"Export/Customs Declaration","location":"","requiredWhen":"","instruction":"Return only the declaration reference value. Remove labels and words before it. Remove hyphens and other decorative punctuation, but preserve forward slashes.","portalFieldIds":["exportDeclarationReference"],"ruleIds":[]},{"id":"mg-source-exportDeclarationDate","label":"Export Declaration Issuance Date","document":"Export/Customs Declaration","location":"","requiredWhen":"","instruction":"Read the declaration issue date and normalize it to YYYY-MM-DD. Leave blank if the date is incomplete or genuinely ambiguous.","portalFieldIds":["exportDeclarationDate"],"ruleIds":[]}],"mappings":[],"sources":[],"aliases":[]},"revision":0,"version":null,"publishedAt":null},{"id":"mg-system","title":"System Guide","template":"system","country":"Madagascar","content":{"sections":[{"heading":"Portal","text":"","references":[]},{"heading":"Navigation","text":"","references":[]},{"heading":"Submission","text":"","references":[]},{"heading":"Statuses","text":"","references":[]},{"heading":"Corrections","text":"","references":[]},{"heading":"Sources","text":"","references":[]}],"rules":[],"fields":[],"mappings":[],"sources":[],"aliases":[]},"revision":0,"version":null,"publishedAt":null},{"id":"mg-field-map","title":"Field Map","template":"mappings","country":"Madagascar","content":{"sections":[{"heading":"System Field Map","text":"","references":[]}],"rules":[],"fields":[],"mappings":[{"id":"mg-map-exporterName","systemFieldId":"exporterName","sourceFieldIds":["mg-source-exporterName"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-exporterAddress","systemFieldId":"exporterAddress","sourceFieldIds":["mg-source-exporterAddress"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-exporterCountry","systemFieldId":"exporterCountry","sourceFieldIds":["mg-source-exporterCountry"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-importerName","systemFieldId":"importerName","sourceFieldIds":["mg-source-importerName"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-importerAddress","systemFieldId":"importerAddress","sourceFieldIds":["mg-source-importerAddress"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-importerCountry","systemFieldId":"importerCountry","sourceFieldIds":["mg-source-importerCountry"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-incoterm","systemFieldId":"incoterm","sourceFieldIds":["mg-source-incoterm"],"entryRule":"Read an explicitly stated Incoterm first. If it is absent, infer it from the Commercial Invoice''s value composition: when the only stated total is Commercial Value, Goods Value, Merchandise Value or an equivalent goods total and the invoice does not add freight or insurance, return FOB; use CFR when the invoiced total includes goods plus freight; use CIF when the invoiced total includes goods plus freight plus insurance. A separately itemized freight or insurance amount is evidence of inclusion only when the invoice total or wording shows that it is part of the invoiced value. The commercial-value-only case must not be left blank merely because the letters FOB are not printed. Return the three-letter uppercase term and keep it consistent with Incoterm Place and FOB Value. Leave blank only when the documented amounts genuinely support more than one case.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"uppercase","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-incotermPlace","systemFieldId":"incotermPlace","sourceFieldIds":["mg-source-incotermPlace"],"entryRule":"Derive this together with Incoterm. For FOB, use the named port or place of loading. For CFR or CIF, use the named destination or port of discharge. Prefer the place printed beside the Incoterm, then the corresponding named port elsewhere on the Commercial Invoice. Preserve the port or city name. Leave blank only when the invoice does not identify the required place.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-fobValue","systemFieldId":"fobValue","sourceFieldIds":["mg-source-fobValue"],"entryRule":"Return the total FOB goods value as a decimal number without a currency symbol or thousands separators. Prefer an explicitly labeled FOB total. Otherwise derive it from the Commercial Invoice: for FOB, use the total commercial or goods value; for CFR, subtract separately stated freight from the CFR invoice total; for CIF, subtract separately stated freight and insurance from the CIF invoice total. If no reliable total is printed but all line amounts are present, sum the line amounts; calculate quantity multiplied by unit price only when needed. Derive this together with Incoterm and Incoterm Place, use only amounts from this invoice, and leave blank if the necessary components are ambiguous or incomplete.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-currency","systemFieldId":"currency","sourceFieldIds":["mg-source-currency"],"entryRule":"Return an ISO currency code. Normalize an unambiguous symbol: $ to USD, € to EUR and £ to GBP. Use document context when a symbol can denote more than one currency; leave blank if it remains ambiguous.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"uppercase","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-commercialInvoiceReference","systemFieldId":"commercialInvoiceReference","sourceFieldIds":["mg-source-commercialInvoiceReference"],"entryRule":"Return only the reference value. Remove labels and words before it, such as Invoice or Invoice #. Remove hyphens and other decorative punctuation, but preserve forward slashes. Example: Invoice # 81 becomes 81.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-commercialInvoiceDate","systemFieldId":"commercialInvoiceDate","sourceFieldIds":["mg-source-commercialInvoiceDate"],"entryRule":"Read the invoice issue date and normalize it to YYYY-MM-DD. Resolve day and month order from the document''s locale and surrounding text. Leave blank if the date is incomplete or genuinely ambiguous.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"date-iso","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-packingListReference","systemFieldId":"packingListReference","sourceFieldIds":["mg-source-packingListReference"],"entryRule":"Return only the reference value. Remove labels and words before it. Remove hyphens and other decorative punctuation, but preserve forward slashes.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-packingListDate","systemFieldId":"packingListDate","sourceFieldIds":["mg-source-packingListDate"],"entryRule":"Read the packing-list issue date and normalize it to YYYY-MM-DD. Leave blank if the date is incomplete or genuinely ambiguous.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"date-iso","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-shipmentMethod","systemFieldId":"shipmentMethod","sourceFieldIds":["mg-source-shipmentMethod"],"entryRule":"Return Sea for an ocean, liner, sea waybill or maritime Bill of Lading. Return Air for an airway bill or air waybill. Do not infer another method.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-cargoType","systemFieldId":"cargoType","sourceFieldIds":["mg-source-cargoType"],"entryRule":"Return Full container load when the Bill of Lading identifies one or more shipping containers. Otherwise use only an explicitly supported cargo type and leave blank when it cannot be determined.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-grossWeight","systemFieldId":"grossWeight","sourceFieldIds":["mg-source-grossWeight"],"entryRule":"Return the total gross shipment weight required by the certificate, normalized to kilograms as a decimal number without a unit suffix. Prefer an explicitly labeled total gross weight. Convert another explicit weight unit to kilograms only when the source unit is clear.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"decimal","unit":"kg","repeated":false,"ruleIds":[]},{"id":"mg-map-volume","systemFieldId":"volume","sourceFieldIds":["mg-source-volume"],"entryRule":"Return explicit shipment volume in cubic metres as a decimal number without a unit suffix. If volume is absent but container sizes are explicit, use 25 per 20-foot container and 50 per 40-foot container and sum multiple containers. Otherwise leave blank.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"decimal","unit":"m³","repeated":false,"ruleIds":[]},{"id":"mg-map-shippingLine","systemFieldId":"shippingLine","sourceFieldIds":["mg-source-shippingLine"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-voyage","systemFieldId":"voyage","sourceFieldIds":["mg-source-voyage"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-vessel","systemFieldId":"vessel","sourceFieldIds":["mg-source-vessel"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-containerNumber","systemFieldId":"containerNumber","sourceFieldIds":["mg-source-containerNumber"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-containerType","systemFieldId":"containerType","sourceFieldIds":["mg-source-containerType"],"entryRule":"Normalize container notation to an allowed certificate option. RF or RH means Reefer; OT means Open Top; FR means FlatRack; TK means Tank; DV, DC, GP, HC or HQ normally means Dry unless other evidence establishes a different type. Use the full container code and description together and leave blank if uncertain.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-containerSize","systemFieldId":"containerSize","sourceFieldIds":["mg-source-containerSize"],"entryRule":"Normalize an explicit container size to the exact allowed certificate option: a 20-foot code to 20 Feet and a 40-foot code to 40 Feet. Use Other for another explicit length. Leave blank when no size is stated or encoded.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-sealNumber","systemFieldId":"sealNumber","sourceFieldIds":["mg-source-sealNumber"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-loadingCountry","systemFieldId":"loadingCountry","sourceFieldIds":["mg-source-loadingCountry"],"entryRule":"Return the country containing the named port or place of loading, using the exact allowed country name. Geographic lookup is permitted when the port is explicit; for example, Newark is in the United States.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-loadingDate","systemFieldId":"loadingDate","sourceFieldIds":["mg-source-loadingDate"],"entryRule":"Use an explicitly stated departure or shipped-on-board date and normalize it to YYYY-MM-DD. Do not invent a current schedule date; leave blank for later carrier tracking when it is not in the documents.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"date-iso","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-loadingCity","systemFieldId":"loadingCity","sourceFieldIds":["mg-source-loadingCity"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-unloadingCountry","systemFieldId":"unloadingCountry","sourceFieldIds":["mg-source-unloadingCountry"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-unloadingDate","systemFieldId":"unloadingDate","sourceFieldIds":["mg-source-unloadingDate"],"entryRule":"Use an explicitly stated arrival or unloading date and normalize it to YYYY-MM-DD. Do not invent a current schedule date; leave blank for later carrier tracking when it is not in the documents.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"date-iso","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-unloadingCity","systemFieldId":"unloadingCity","sourceFieldIds":["mg-source-unloadingCity"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-exportDeclarationReference","systemFieldId":"exportDeclarationReference","sourceFieldIds":["mg-source-exportDeclarationReference"],"entryRule":"Return only the declaration reference value. Remove labels and words before it. Remove hyphens and other decorative punctuation, but preserve forward slashes.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-exportDeclarationDate","systemFieldId":"exportDeclarationDate","sourceFieldIds":["mg-source-exportDeclarationDate"],"entryRule":"Read the declaration issue date and normalize it to YYYY-MM-DD. Leave blank if the date is incomplete or genuinely ambiguous.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"date-iso","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-billOfLadingReference","systemFieldId":"billOfLadingReference","sourceFieldIds":["mg-source-billOfLadingReference"],"entryRule":"Return only the Bill of Lading or waybill number. Remove labels and words before it. Remove hyphens and other decorative punctuation, but preserve forward slashes.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-billOfLadingDate","systemFieldId":"billOfLadingDate","sourceFieldIds":["mg-source-billOfLadingDate"],"entryRule":"Read the Bill of Lading or waybill issue date and normalize it to YYYY-MM-DD. Keep shipped-on-board and issue dates distinct. Leave blank if the issue date is not present.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"date-iso","unit":"","repeated":false,"ruleIds":[]},{"id":"mg-map-invoiceItems-hsCode","systemFieldId":"invoiceItems.hsCode","sourceFieldIds":["mg-source-invoiceItems-hsCode"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":true,"ruleIds":[]},{"id":"mg-map-invoiceItems-description","systemFieldId":"invoiceItems.description","sourceFieldIds":["mg-source-invoiceItems-description"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":true,"ruleIds":[]},{"id":"mg-map-invoiceItems-quantity","systemFieldId":"invoiceItems.quantity","sourceFieldIds":["mg-source-invoiceItems-quantity"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":true,"ruleIds":[]},{"id":"mg-map-invoiceItems-unitOfMeasurement","systemFieldId":"invoiceItems.unitOfMeasurement","sourceFieldIds":["mg-source-invoiceItems-unitOfMeasurement"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":true,"ruleIds":[]},{"id":"mg-map-invoiceItems-unitPrice","systemFieldId":"invoiceItems.unitPrice","sourceFieldIds":["mg-source-invoiceItems-unitPrice"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":true,"ruleIds":[]},{"id":"mg-map-invoiceItems-isSecondHand","systemFieldId":"invoiceItems.isSecondHand","sourceFieldIds":["mg-source-invoiceItems-isSecondHand"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":true,"ruleIds":[]},{"id":"mg-map-invoiceItems-originCountry","systemFieldId":"invoiceItems.originCountry","sourceFieldIds":["mg-source-invoiceItems-originCountry"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":true,"ruleIds":[]},{"id":"mg-map-invoiceValues","systemFieldId":"invoiceValues","sourceFieldIds":["mg-source-invoiceValues"],"entryRule":"Use the documented value and existing dropdown options.","ifMissing":"Leave blank and flag for staff review.","fallbackSourceIds":[],"transform":"none","unit":"","repeated":true,"ruleIds":[]}],"sources":[],"aliases":[]},"revision":0,"version":null,"publishedAt":null},{"